inline bool encode_Patch(Writer& w, const Patch& v) {
  if (!w.u32(v.generation)) return false;
  if (!w.u32(v.sequence)) return false;
  if (!w.u16(v.flags)) return false;
  if (!w.u32(v.builtAt)) return false;
  if (v.metrics_count > 16) return false;
  if (!w.u8(v.metrics_count)) return false;
  for (uint8_t i = 0; i < v.metrics_count; ++i) {
    if (!encode_Metric(w, v.metrics[i])) return false;
  }
  if (!w.bytes(v.deltas)) return false;
  return w.ok();
}
inline bool decode_Patch(Reader& r, Patch& v) {
  if (!r.u32(v.generation)) return false;
  if (!r.u32(v.sequence)) return false;
  if (!r.u16(v.flags)) return false;
  if (!r.u32(v.builtAt)) return false;
  if (!r.u8(v.metrics_count)) return false;
  if (v.metrics_count > 16) return false;
  for (uint8_t i = 0; i < v.metrics_count; ++i) {
    if (!decode_Metric(r, v.metrics[i])) return false;
  }
  if (!r.bytes(v.deltas)) return false;
  return r.ok();
}

