inline bool encode_Fault(Writer& w, const Fault& v) {
  if (!w.u16(static_cast<uint16_t>(v.code))) return false;
  if (!w.u32(v.flags)) return false;
  if (!w.str(v.origin)) return false;
  if (!w.str(v.message)) return false;
  if (v.data_count > 8) return false;
  if (!w.u8(v.data_count)) return false;
  for (uint8_t i = 0; i < v.data_count; ++i) {
    if (!encode_FaultDatum(w, v.data[i])) return false;
  }
  return w.ok();
}
inline bool decode_Fault(Reader& r, Fault& v) {
  uint16_t _e_code{};
  if (!r.u16(_e_code)) return false;
  v.code = static_cast<FaultCode>(_e_code);
  if (!r.u32(v.flags)) return false;
  if (!r.str(v.origin)) return false;
  if (!r.str(v.message)) return false;
  if (!r.u8(v.data_count)) return false;
  if (v.data_count > 8) return false;
  for (uint8_t i = 0; i < v.data_count; ++i) {
    if (!decode_FaultDatum(r, v.data[i])) return false;
  }
  return r.ok();
}

