inline const char* opcodeName(uint16_t op) {
  switch (op) {
    case 0x0F10: return "FreezeAll";
    case 0x0F11: return "CaptureState";
    case 0x0F12: return "ThawAll";
    case 0x0F01: return "Probe";
    case 0x0101: return "Shutdown";
    case 0x0102: return "ViewportOpen";
    case 0x0201: return "ViewportClose";
    case 0x0202: return "ViewportResize";
    case 0x0301: return "Navigate";
    case 0x0302: return "Reload";
    case 0x0303: return "StopLoad";
    case 0x0304: return "HistoryGo";
    case 0x0305: return "HostResize";
    case 0x0306: return "Resync";
    case 0x0307: return "ClocksHalt";
    case 0x0308: return "ClocksResume";
    case 0x0309: return "PromptRespond";
    case 0x0401: return "Flush";
    case 0x0402: return "Snapshot";
    case 0x0410: return "InputPointerDown";
    case 0x0411: return "InputPointerUp";
    case 0x0412: return "InputKeyDown";
    case 0x0413: return "InputKeyUp";
    case 0x0414: return "InputScroll";
    case 0x0420: return "AssetRequest";
    case 0x0421: return "AssetCancel";
    case 0x8101: return "Ready";
    case 0x8102: return "Heartbeat";
    case 0x8201: return "ViewportOpened";
    case 0x8202: return "ViewportClosed";
    case 0x8301: return "HostAttached";
    case 0x8302: return "HostDetached";
    case 0x8303: return "DocumentInstalled";
    case 0x8304: return "DocumentDiscarded";
    case 0x8305: return "Navigated";
    case 0x8306: return "LoadStateChanged";
    case 0x8307: return "PromptRequested";
    case 0x8308: return "PromptAbandoned";
    case 0x8401: return "Patch";
    case 0x8402: return "Snapshotted";
    case 0x8420: return "AssetChunk";
    case 0x8421: return "AssetEnd";
    case 0x8422: return "AssetDenied";
    case 0x8F01: return "Fault";
    case 0x8F10: return "FreezeResult";
    case 0x8F11: return "StateCaptured";
    case 0x8F03: return "ProbeResult";
    case 0x8F02: return "Telemetry";
    default: return nullptr;
  }
}

